window.ANATEL_QUESTIONS=[{"id":"L001","subject":"leg","classes":"CBA","text":"O COER é expedido gratuitamente após a aprovação nas matérias exigidas para a classe pretendida.","answer":true,"explanation":"O item 11.1 do Ato nº 3.448/2026 estabelece a expedição gratuita do COER após aprovação nas matérias da classe.","reference":"Ato 3.448/2026, item 11.1","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"L002","subject":"leg","classes":"CBA","text":"As provas atuais para radioamador utilizam apenas questões de múltipla escolha com quatro alternativas.","answer":false,"explanation":"O formato atual previsto no item 11.2 é objetivo na modalidade Certo ou Errado.","reference":"Ato 3.448/2026, item 11.2","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"L003","subject":"leg","classes":"CBA","text":"Na Classe C, cada uma das três matérias possui 15 questões e exige no mínimo 8 acertos.","answer":true,"explanation":"A tabela do item 11.3 fixa 15 questões e mínimo de 8 acertos em cada matéria da Classe C.","reference":"Ato 3.448/2026, item 11.3","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"L004","subject":"leg","classes":"CBA","text":"Na Classe C, o tempo máximo previsto para cada matéria é de 20 minutos.","answer":true,"explanation":"A tabela do item 11.3 estabelece 20 minutos por matéria para a Classe C.","reference":"Ato 3.448/2026, item 11.3","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"L005","subject":"leg","classes":"CBA","text":"Na Classe B, cada matéria possui 20 questões e exige no mínimo 11 acertos.","answer":true,"explanation":"A tabela do item 11.3 fixa 20 questões e mínimo de 11 acertos em cada matéria da Classe B.","reference":"Ato 3.448/2026, item 11.3","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"L006","subject":"leg","classes":"CBA","text":"Na Classe B, o tempo máximo previsto é de 20 minutos por matéria.","answer":false,"explanation":"Para a Classe B, o tempo máximo é de 30 minutos por matéria.","reference":"Ato 3.448/2026, item 11.3","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"L007","subject":"leg","classes":"CBA","text":"Na Classe A, cada matéria possui 30 questões e exige no mínimo 16 acertos.","answer":true,"explanation":"A tabela do item 11.3 fixa 30 questões e mínimo de 16 acertos em cada matéria da Classe A.","reference":"Ato 3.448/2026, item 11.3","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"L008","subject":"leg","classes":"CBA","text":"Na Classe A, o tempo máximo previsto é de 40 minutos por matéria.","answer":true,"explanation":"A tabela do item 11.3 estabelece 40 minutos por matéria para a Classe A.","reference":"Ato 3.448/2026, item 11.3","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"L009","subject":"leg","classes":"CBA","text":"A aprovação em uma matéria da prova pode ser aproveitada por 12 meses.","answer":true,"explanation":"Os créditos decorrentes de aprovação em matérias valem por 12 meses.","reference":"Ato 3.448/2026, item 11.8","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"L010","subject":"leg","classes":"CBA","text":"Após reprovação, uma nova tentativa da matéria pode ser feita no dia seguinte.","answer":false,"explanation":"A nova tentativa deve respeitar carência mínima de 8 dias contados da última reprovação.","reference":"Ato 3.448/2026, item 11.8.2","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"L011","subject":"leg","classes":"CBA","text":"A ausência sem justificativa pode impedir novas inscrições por 30 dias corridos.","answer":true,"explanation":"O item 11.7 prevê impedimento de novas inscrições por 30 dias corridos.","reference":"Ato 3.448/2026, item 11.7","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"L012","subject":"leg","classes":"CBA","text":"O candidato pode requerer revisão dos testes no prazo de 60 dias após a publicação do resultado.","answer":true,"explanation":"O item 11.9 prevê 60 dias para requerer revisão por meio do SEI.","reference":"Ato 3.448/2026, item 11.9","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"L013","subject":"leg","classes":"CBA","text":"Menores de idade podem ser inscritos para as provas por seus responsáveis legais através do SEI da Anatel.","answer":true,"explanation":"O item 11.10 prevê a inscrição de menores pelos responsáveis legais via SEI.","reference":"Ato 3.448/2026, item 11.10","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"L014","subject":"leg","classes":"CBA","text":"O conteúdo programático da prova inclui Legislação, Técnica e Ética Operacional e Eletrônica/Eletricidade.","answer":true,"explanation":"O item 11.4 apresenta essas três áreas, com nível de eletrônica adequado a cada classe.","reference":"Ato 3.448/2026, item 11.4","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"L015","subject":"leg","classes":"CBA","text":"Para a Classe B, o conteúdo de eletrônica exclui o conteúdo básico exigido na Classe C.","answer":false,"explanation":"A ementa da Classe B inclui todo o conteúdo de Conhecimentos Básicos de Eletrônica e Eletricidade da Classe C.","reference":"Ato 3.448/2026, item 11.4","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"L016","subject":"leg","classes":"CBA","text":"Para a Classe A, o conteúdo técnico inclui também o conteúdo exigido para a Classe B.","answer":true,"explanation":"A ementa da Classe A começa incluindo todo o conteúdo especificado nos Conhecimentos de Eletrônica e Eletricidade da Classe B.","reference":"Ato 3.448/2026, item 11.4","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"L017","subject":"leg","classes":"CBA","text":"O COER é intransferível e possui prazo de validade indeterminado.","answer":true,"explanation":"O art. 275 do RGST define o COER como intransferível e de validade indeterminada.","reference":"Resolução 777/2025 (RGST), art. 275","url":"https://informacoes.anatel.gov.br/legislacao/resolucoes/2025/2022-resolucao-777"},{"id":"L018","subject":"leg","classes":"CBA","text":"Somente brasileiros maiores de 18 anos podem obter COER.","answer":false,"explanation":"O art. 275 permite que qualquer pessoa física residente no Brasil obtenha COER, observados os procedimentos aplicáveis.","reference":"Resolução 777/2025 (RGST), art. 275","url":"https://informacoes.anatel.gov.br/legislacao/resolucoes/2025/2022-resolucao-777"},{"id":"L019","subject":"leg","classes":"CBA","text":"O Serviço de Radioamador é serviço de telecomunicações de interesse restrito.","answer":true,"explanation":"O art. 26 do RGST caracteriza o Serviço de Radioamador como serviço de interesse restrito, em regime privado.","reference":"Resolução 777/2025 (RGST), art. 26","url":"https://informacoes.anatel.gov.br/legislacao/resolucoes/2025/2022-resolucao-777"},{"id":"L020","subject":"leg","classes":"CBA","text":"O Serviço de Radioamador pode ter objetivo comercial ou pecuniário desde que a estação seja licenciada.","answer":false,"explanation":"O art. 26 define o serviço para treinamento, intercomunicação e investigações técnicas a título pessoal, sem objetivo pecuniário ou comercial.","reference":"Resolução 777/2025 (RGST), art. 26","url":"https://informacoes.anatel.gov.br/legislacao/resolucoes/2025/2022-resolucao-777"},{"id":"L021","subject":"leg","classes":"CBA","text":"Um maior de 18 anos portador de COER Classe C pode prestar os testes específicos para Classe B sem esperar dois anos.","answer":true,"explanation":"O art. 277, II, aplica o prazo de dois anos aos menores de 18; os maiores de 18 podem progredir mediante aprovação nos testes da Classe B.","reference":"Resolução 777/2025 (RGST), art. 277, II","url":"https://informacoes.anatel.gov.br/legislacao/resolucoes/2025/2022-resolucao-777"},{"id":"L022","subject":"leg","classes":"CBA","text":"Um menor de 18 anos Classe C precisa aguardar dois anos da expedição do COER C para se inscrever na mudança para Classe B.","answer":true,"explanation":"O art. 277, II, prevê dois anos para portadores Classe C menores de 18 anos.","reference":"Resolução 777/2025 (RGST), art. 277, II","url":"https://informacoes.anatel.gov.br/legislacao/resolucoes/2025/2022-resolucao-777"},{"id":"L023","subject":"leg","classes":"CBA","text":"Para chegar à Classe A, o radioamador deve possuir Classe B há pelo menos um ano e ser aprovado nos testes específicos da Classe A.","answer":true,"explanation":"O art. 277, III, exige um ano desde a expedição do COER B e aprovação nos testes da Classe A.","reference":"Resolução 777/2025 (RGST), art. 277, III","url":"https://informacoes.anatel.gov.br/legislacao/resolucoes/2025/2022-resolucao-777"},{"id":"L024","subject":"leg","classes":"CBA","text":"As inscrições para mudança de classe podem ser feitas antes do encerramento do prazo regulamentar, desde que a prova ocorra depois.","answer":false,"explanation":"O §1º do art. 277 determina que as inscrições para mudança de classe somente podem ser efetuadas após encerrados os prazos aplicáveis.","reference":"Resolução 777/2025 (RGST), art. 277 §1º","url":"https://informacoes.anatel.gov.br/legislacao/resolucoes/2025/2022-resolucao-777"},{"id":"L025","subject":"leg","classes":"CBA","text":"Estação fixa, repetidora, móvel, terrena e espacial são tipos de estação previstos para o Serviço de Radioamador.","answer":true,"explanation":"O art. 10-B do Regulamento Geral de Licenciamento, incluído pela Resolução 777/2025, enumera esses tipos.","reference":"Resolução 777/2025, art. 14 (RGL art. 10-B)","url":"https://informacoes.anatel.gov.br/legislacao/resolucoes/2025/2022-resolucao-777"},{"id":"L026","subject":"leg","classes":"CBA","text":"Uma estação móvel é definida como aquela instalada obrigatoriamente em um endereço fixo específico.","answer":false,"explanation":"Estação móvel é destinada a uso em movimento ou durante paradas em pontos não especificados.","reference":"Resolução 777/2025, RGL art. 10-B, III","url":"https://informacoes.anatel.gov.br/legislacao/resolucoes/2025/2022-resolucao-777"},{"id":"L027","subject":"leg","classes":"CBA","text":"É vedado usar uma estação de radioamador conectada a outras redes para fazer tráfego entre essas redes, salvo em emergência.","answer":true,"explanation":"O §2º do art. 10-B veda a fruição de tráfego entre redes, exceto em caso de emergência.","reference":"Resolução 777/2025, RGL art. 10-B §2º","url":"https://informacoes.anatel.gov.br/legislacao/resolucoes/2025/2022-resolucao-777"},{"id":"L028","subject":"leg","classes":"CBA","text":"O radioamador pode modificar equipamentos para adequá-los à legislação, realizar experimentos ou melhorar desempenho, assumindo responsabilidade pelas modificações.","answer":true,"explanation":"O art. 283 do RGST permite modificações e atribui responsabilidade ao radioamador.","reference":"Resolução 777/2025 (RGST), art. 283","url":"https://informacoes.anatel.gov.br/legislacao/resolucoes/2025/2022-resolucao-777"},{"id":"L029","subject":"leg","classes":"CBA","text":"Compete à Anatel atribuir os indicativos de chamada do Serviço de Radioamador.","answer":true,"explanation":"O art. 284 do RGST atribui essa competência à Anatel.","reference":"Resolução 777/2025 (RGST), art. 284","url":"https://informacoes.anatel.gov.br/legislacao/resolucoes/2025/2022-resolucao-777"},{"id":"L030","subject":"leg","classes":"CBA","text":"Indicativos especiais destinam-se apenas ao uso cotidiano e têm validade indeterminada.","answer":false,"explanation":"Indicativos especiais são destinados a competições, expedições e eventos, limitados ao período de duração do evento.","reference":"Resolução 777/2025 (RGST), art. 285, II","url":"https://informacoes.anatel.gov.br/legislacao/resolucoes/2025/2022-resolucao-777"},{"id":"L031","subject":"leg","classes":"CBA","text":"A escolha do indicativo efetivo pode ser feita pelo radioamador, desde que esteja disponível.","answer":true,"explanation":"O item 12.1 do Ato 3.448/2026 faculta a escolha do indicativo efetivo quando disponível.","reference":"Ato 3.448/2026, item 12.1","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"L032","subject":"leg","classes":"CBA","text":"O mesmo indicativo pode ser compartilhado simultaneamente por duas estações do mesmo titular.","answer":false,"explanation":"O item 12.8 veda o compartilhamento ou uso simultâneo do mesmo indicativo entre estações.","reference":"Ato 3.448/2026, item 12.8","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"L033","subject":"leg","classes":"CBA","text":"Para a Classe C, os indicativos efetivos utilizam o prefixo PU conforme a Unidade da Federação.","answer":true,"explanation":"O item 12.10.3 prevê prefixo PU, número de região e agrupamento de três letras para Classe C.","reference":"Ato 3.448/2026, item 12.10.3","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"L034","subject":"leg","classes":"CBA","text":"Se a documentação de um radioamador estrangeiro não permitir identificar a classe equivalente no Brasil, a licença será expedida na Classe C.","answer":true,"explanation":"O item 8.4 determina a Classe C quando a equivalência não puder ser corretamente identificada.","reference":"Ato 3.448/2026, item 8.4","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"L035","subject":"leg","classes":"CBA","text":"A regulamentação atual permite ao candidato prestar provas online, conforme calendário do SEC.","answer":true,"explanation":"A página oficial de habilitação informa aplicação online via internet e agendamento pelo SEC.","reference":"ANATEL — Habilitação do Radioamador, atualização 11/06/2026","url":"https://www.gov.br/anatel/pt-br/regulado/outorga/radioamador-e-radio-cidadao/habilitacao-do-radioamador"},{"id":"L036","subject":"leg","classes":"CBA","text":"O SEC informa que as provas são elaboradas com sorteio aleatório de questões e correção automatizada.","answer":true,"explanation":"A descrição oficial do SEC informa sorteio aleatório de questões, correção e avaliação automatizadas.","reference":"ANATEL — Sistema SEC","url":"https://sistemas.anatel.gov.br/sis/LoginInternet.asp?Pagina=http%3A%2F%2Fsistemas.anatel.gov.br%2Fsec%2FDefault.asp%3F&codSistema=435"},{"id":"L037","subject":"leg","classes":"CBA","text":"O Plano de Atribuição, Destinação e Distribuição de Faixas de Frequências vigente em julho de 2026 foi aprovado pela Resolução nº 789/2026.","answer":true,"explanation":"A Resolução 789, de 6 de julho de 2026, aprova o PDFF e aparece como vigente no repositório oficial da Anatel.","reference":"Resolução 789/2026 — PDFF","url":"https://informacoes.anatel.gov.br/legislacao/resolucoes/2026/2157-resolucao-789"},{"id":"L038","subject":"leg","classes":"CBA","text":"O Ato nº 926/2024 está revogado e não deve ser usado para o plano de faixas do radioamador.","answer":false,"explanation":"O Ato 926/2024 continua identificado como vigente pela Anatel e estabelece requisitos técnicos e operacionais, inclusive classes e plano de faixas.","reference":"Ato 926/2024 — vigente","url":"https://informacoes.anatel.gov.br/legislacao/component/content/article/165-atos-de-requisitos-tecnicos-de-gestao-do-espectro/2024/1919-ato-926"},{"id":"L039","subject":"leg","classes":"CBA","text":"A habilitação para obtenção do COER é gratuita.","answer":true,"explanation":"A página oficial da Anatel informa que a habilitação e a emissão do COER são gratuitas.","reference":"ANATEL — Habilitação do Radioamador","url":"https://www.gov.br/anatel/pt-br/regulado/outorga/radioamador-e-radio-cidadao/habilitacao-do-radioamador"},{"id":"L040","subject":"leg","classes":"CBA","text":"O licenciamento de estação é obrigatório para que uma pessoa possa possuir COER.","answer":false,"explanation":"A Anatel informa que o COER é a habilitação do operador; o licenciamento de estação própria é etapa distinta e opcional para quem deseje possuir estação própria.","reference":"ANATEL — Habilitação/Radioamadorismo","url":"https://www.gov.br/anatel/pt-br/regulado/outorga/radioamador-e-radio-cidadao/habilitacao-do-radioamador"},{"id":"O001","subject":"op","classes":"CBA","text":"Antes de transmitir, o operador deve verificar se o canal está livre.","answer":true,"explanation":"Essa verificação é exigida pelo item 10.3, I.","reference":"Ato 3.448/2026, item 10.3, I","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O002","subject":"op","classes":"CBA","text":"Uma chamada pode ser repetida quantas vezes forem necessárias até alguém responder.","answer":false,"explanation":"A chamada pode ser repetida no máximo três vezes consecutivas e depois o operador deve passar à escuta.","reference":"Ato 3.448/2026, item 10.3, II","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O003","subject":"op","classes":"CBA","text":"Uma vez estabelecida a comunicação, devem ser mencionados os indicativos das duas estações em contato.","answer":true,"explanation":"O item 10.3, III, exige a identificação das duas estações.","reference":"Ato 3.448/2026, item 10.3, III","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O004","subject":"op","classes":"CBA","text":"O indicativo pode ser abreviado durante o comunicado se as duas estações já se identificaram no início.","answer":false,"explanation":"O indicativo deve ser declarado completo, sem supressões ou acréscimos.","reference":"Ato 3.448/2026, item 10.3, IV","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O005","subject":"op","classes":"CBA","text":"A transmissão entre estações deve se limitar, em regra, a 10 minutos, exceto em emergência.","answer":true,"explanation":"O item 10.3, V, fixa duração máxima de 10 minutos, com exceção de emergência.","reference":"Ato 3.448/2026, item 10.3, V","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O006","subject":"op","classes":"CBA","text":"Nas comunicações entre radioamadores é permitido o Código Q das séries QRA a QUZ.","answer":true,"explanation":"O item 10.4 permite Código Q limitado às séries QRA a QUZ.","reference":"Ato 3.448/2026, item 10.4","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O007","subject":"op","classes":"CBA","text":"A operação de uma estação sem identificação é permitida durante testes curtos.","answer":false,"explanation":"O item 10.2 veda a operação de estação sem identificação.","reference":"Ato 3.448/2026, item 10.2","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O008","subject":"op","classes":"CBA","text":"Uma repetidora deve transmitir automaticamente seu indicativo em intervalos não superiores a uma hora.","answer":true,"explanation":"Essa exigência está no item 10.5.1.","reference":"Ato 3.448/2026, item 10.5.1","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O009","subject":"op","classes":"CBA","text":"Uma repetidora pode manter a transmissão por até 30 segundos após desaparecer o sinal de entrada.","answer":false,"explanation":"O máximo previsto é de cinco segundos.","reference":"Ato 3.448/2026, item 10.5.2","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O010","subject":"op","classes":"CBA","text":"O uso continuado de uma repetidora não deve exceder 10 minutos e deve haver desligamento automático.","answer":true,"explanation":"O item 10.5.3 prevê o limite e o dispositivo de desligamento automático.","reference":"Ato 3.448/2026, item 10.5.3","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O011","subject":"op","classes":"CBA","text":"Repetidoras podem ser fechadas por codificação com o objetivo de restringir a comunicação apenas a um grupo privado.","answer":false,"explanation":"As repetidoras devem ser abertas a todos os radioamadores, observadas as classes, sem codificação para restringir comunicação, ressalvado telecomando espacial.","reference":"Ato 3.448/2026, item 10.5.5","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O012","subject":"op","classes":"CBA","text":"Comunicações de emergência têm prioridade sobre as demais aplicações do Serviço de Radioamador.","answer":true,"explanation":"O Ato 926/2024 estabelece prioridade às comunicações emergenciais.","reference":"Ato 926/2024, item 6.4","url":"https://informacoes.anatel.gov.br/legislacao/component/content/article/165-atos-de-requisitos-tecnicos-de-gestao-do-espectro/2024/1919-ato-926"},{"id":"O013","subject":"op","classes":"CBA","text":"É permitida criptografia nas aplicações de Modos Digitais e Voz Digital quando os operadores concordam.","answer":false,"explanation":"O Ato 926/2024 não permite criptografia nessas aplicações.","reference":"Ato 926/2024, item 6.11","url":"https://informacoes.anatel.gov.br/legislacao/component/content/article/165-atos-de-requisitos-tecnicos-de-gestao-do-espectro/2024/1919-ato-926"},{"id":"O014","subject":"op","classes":"CBA","text":"Salto em frequência e espalhamento espectral não são permitidos em faixas abaixo de 440 MHz.","answer":true,"explanation":"O Ato 926/2024 estabelece essa restrição.","reference":"Ato 926/2024, item 6.12","url":"https://informacoes.anatel.gov.br/legislacao/component/content/article/165-atos-de-requisitos-tecnicos-de-gestao-do-espectro/2024/1919-ato-926"},{"id":"O015","subject":"op","classes":"CBA","text":"A potência usada deve ser a mínima necessária para realizar o serviço com boa qualidade e confiabilidade.","answer":true,"explanation":"Esse é o princípio do item 5.1 do Ato 926/2024.","reference":"Ato 926/2024, item 5.1","url":"https://informacoes.anatel.gov.br/legislacao/component/content/article/165-atos-de-requisitos-tecnicos-de-gestao-do-espectro/2024/1919-ato-926"},{"id":"O016","subject":"op","classes":"CBA","text":"O limite geral de potência média na saída do transmissor para Classe C é 100 W, ressalvados limites específicos.","answer":true,"explanation":"O item 5.2, III, fixa 100 W para Classe C, ressalvadas condições específicas.","reference":"Ato 926/2024, item 5.2, III","url":"https://informacoes.anatel.gov.br/legislacao/component/content/article/165-atos-de-requisitos-tecnicos-de-gestao-do-espectro/2024/1919-ato-926"},{"id":"O017","subject":"op","classes":"CBA","text":"O limite geral de potência média na saída do transmissor para Classe B é 1.000 W, ressalvados limites específicos.","answer":true,"explanation":"O item 5.2, II, fixa 1.000 W para Classe B.","reference":"Ato 926/2024, item 5.2, II","url":"https://informacoes.anatel.gov.br/legislacao/component/content/article/165-atos-de-requisitos-tecnicos-de-gestao-do-espectro/2024/1919-ato-926"},{"id":"O018","subject":"op","classes":"CBA","text":"O limite geral de potência média na saída do transmissor para Classe A é 1.500 W, ressalvados limites específicos.","answer":true,"explanation":"O item 5.2, I, fixa 1.500 W para Classe A.","reference":"Ato 926/2024, item 5.2, I","url":"https://informacoes.anatel.gov.br/legislacao/component/content/article/165-atos-de-requisitos-tecnicos-de-gestao-do-espectro/2024/1919-ato-926"},{"id":"O019","subject":"op","classes":"CBA","text":"Um transceptor reúne funções de transmissão e recepção em um mesmo equipamento.","answer":true,"explanation":"Transceptor é o equipamento que integra transmissor e receptor, conceito básico da ementa técnica.","reference":"Ato 3.448/2026, item 11.4 — Estação de radioamador","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O020","subject":"op","classes":"CBA","text":"Uma carga artificial é usada para testar um transmissor sem irradiar intencionalmente pela antena.","answer":true,"explanation":"A carga artificial dissipa a potência do transmissor e permite testes sem o sistema radiante normal.","reference":"Ato 3.448/2026, item 11.4 — Antenas/carga artificial","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O021","subject":"op","classes":"CBA","text":"Uma ROE próxima de 1:1 indica melhor casamento entre linha de transmissão e carga do que uma ROE elevada.","answer":true,"explanation":"ROE baixa indica menor potência refletida; 1:1 é a condição ideal de casamento.","reference":"Ato 3.448/2026, item 11.4 — onda estacionária","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O022","subject":"op","classes":"CBA","text":"Ao aumentar a frequência de uma onda eletromagnética, seu comprimento de onda aumenta na mesma proporção.","answer":false,"explanation":"Como λ = c/f, aumentando a frequência o comprimento de onda diminui.","reference":"Ato 3.448/2026, item 11.4 — frequência e comprimento de onda","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O023","subject":"op","classes":"CBA","text":"Em HF, a ionosfera pode permitir comunicações a distâncias muito superiores à linha de visada.","answer":true,"explanation":"A propagação ionosférica é um mecanismo importante em HF.","reference":"Ato 3.448/2026, item 11.4 — propagação","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O024","subject":"op","classes":"CBA","text":"VHF e UHF dependem exclusivamente de reflexão ionosférica para qualquer comunicação.","answer":false,"explanation":"VHF/UHF normalmente têm forte componente de propagação por linha de visada e outros fenômenos; não dependem exclusivamente da ionosfera.","reference":"Ato 3.448/2026, item 11.4 — propagação","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O025","subject":"op","classes":"CBA","text":"Uma antena direcional concentra maior energia em determinadas direções do que uma antena idealmente isotrópica.","answer":true,"explanation":"Diretividade descreve a concentração de energia em determinadas direções.","reference":"Ato 3.448/2026, item 11.4 — antenas","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O026","subject":"op","classes":"CBA","text":"QTH é tradicionalmente usado no Código Q para indicar localização ou posição da estação.","answer":true,"explanation":"QTH é um dos códigos operacionais tradicionais abordados na ementa de Código Q.","reference":"Ato 3.448/2026, item 11.4 — Código Q","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O027","subject":"op","classes":"CBA","text":"QRM é usado para indicar interferência causada por outras estações.","answer":true,"explanation":"QRM refere-se a interferência produzida por outras transmissões.","reference":"Ato 3.448/2026, item 11.4 — Código Q","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O028","subject":"op","classes":"CBA","text":"QRN é utilizado para indicar ruído ou estática de origem natural.","answer":true,"explanation":"QRN é empregado para ruído/estática natural.","reference":"Ato 3.448/2026, item 11.4 — Código Q","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O029","subject":"op","classes":"CBA","text":"QSL é tradicionalmente relacionado à confirmação de recepção ou contato.","answer":true,"explanation":"QSL é usado como confirmação/acuse de recepção no contexto operacional.","reference":"Ato 3.448/2026, item 11.4 — Código Q","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O030","subject":"op","classes":"CBA","text":"QSY significa aumentar a potência do transmissor.","answer":false,"explanation":"QSY é empregado para mudança de frequência.","reference":"Ato 3.448/2026, item 11.4 — Código Q","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O031","subject":"op","classes":"CBA","text":"No alfabeto fonético internacional, a letra A é representada por Alfa.","answer":true,"explanation":"O alfabeto fonético da UIT integra a ementa de Técnica e Ética Operacional.","reference":"Ato 3.448/2026, item 11.4 — Alfabeto Fonético UIT","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O032","subject":"op","classes":"CBA","text":"No alfabeto fonético internacional, a letra B é representada por Bravo.","answer":true,"explanation":"Bravo é a palavra fonética internacional para B.","reference":"Ato 3.448/2026, item 11.4 — Alfabeto Fonético UIT","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O033","subject":"op","classes":"CBA","text":"No alfabeto fonético internacional, a letra X é representada por X-ray.","answer":true,"explanation":"X-ray é a palavra fonética internacional para X.","reference":"Ato 3.448/2026, item 11.4 — Alfabeto Fonético UIT","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O034","subject":"op","classes":"CBA","text":"Ao perceber que está causando interferência prejudicial, a conduta adequada é continuar transmitindo até concluir o assunto.","answer":false,"explanation":"A ética operacional e a prevenção de interferências exigem reduzir ou cessar a causa da interferência e corrigir a estação/operação.","reference":"Ato 3.448/2026, item 11.4 — Interferências e Ética","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O035","subject":"op","classes":"CBA","text":"Em situação de emergência, comunicações relacionadas à salvaguarda da vida devem receber prioridade operacional.","answer":true,"explanation":"A regulamentação prioriza comunicações de emergência e a ementa exige procedimentos operacionais de emergência.","reference":"Ato 926/2024 item 6.4 e Ato 3.448/2026 item 11.4","url":"https://informacoes.anatel.gov.br/legislacao/component/content/article/165-atos-de-requisitos-tecnicos-de-gestao-do-espectro/2024/1919-ato-926"},{"id":"O036","subject":"op","classes":"CBA","text":"Em uma repetidora, o sinal recebido pode ser retransmitido automaticamente para outras estações.","answer":true,"explanation":"Essa é a função essencial de uma estação repetidora.","reference":"Resolução 777/2025, RGL art. 10-B, II","url":"https://informacoes.anatel.gov.br/legislacao/resolucoes/2025/2022-resolucao-777"},{"id":"O037","subject":"op","classes":"CBA","text":"Uma linha de transmissão ideal serve para transportar energia de RF entre o transmissor e a antena.","answer":true,"explanation":"Linhas de transmissão fazem parte do conteúdo de estação e conectam fonte e carga de RF.","reference":"Ato 3.448/2026, item 11.4","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O038","subject":"op","classes":"CBA","text":"Relação sinal/ruído maior, mantidas as demais condições, tende a favorecer a inteligibilidade do sinal recebido.","answer":true,"explanation":"Maior relação sinal/ruído significa sinal mais destacado em relação ao ruído.","reference":"Ato 3.448/2026, item 11.4 — relação sinal/ruído","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O039","subject":"op","classes":"CBA","text":"Polarização de uma onda eletromagnética está relacionada à orientação do campo elétrico.","answer":true,"explanation":"Polarização é conceito de propagação/antenas previsto na ementa.","reference":"Ato 3.448/2026, item 11.4","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"O040","subject":"op","classes":"CBA","text":"Ressonância ocorre quando um sistema apresenta resposta característica em determinada frequência, conceito relevante em circuitos e antenas.","answer":true,"explanation":"Ressonância aparece expressamente na ementa técnica das Classes B e A.","reference":"Ato 3.448/2026, item 11.4","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"C001","subject":"elec","classes":"CBA","text":"Em um resistor de 100 Ω percorrido por 0,1 A, a tensão é 10 V.","answer":true,"explanation":"Pela Lei de Ohm, V = R×I = 100×0,1 = 10 V.","reference":"Ato 3.448/2026, ementa Classe C","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"C002","subject":"elec","classes":"CBA","text":"Aplicando 12 V em um resistor de 6 Ω, a corrente é 2 A.","answer":true,"explanation":"I = V/R = 12/6 = 2 A.","reference":"Ato 3.448/2026, ementa Classe C","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"C003","subject":"elec","classes":"CBA","text":"Aplicando 12 V em um resistor de 6 Ω, a potência dissipada é 12 W.","answer":false,"explanation":"P = V×I; como I=2 A, P=24 W.","reference":"Ato 3.448/2026, ementa Classe C","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"C004","subject":"elec","classes":"CBA","text":"Dois resistores de 100 Ω em série equivalem a 200 Ω.","answer":true,"explanation":"Resistências em série se somam.","reference":"Ato 3.448/2026, ementa Classe C","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"C005","subject":"elec","classes":"CBA","text":"Dois resistores iguais de 100 Ω em paralelo equivalem a 200 Ω.","answer":false,"explanation":"Dois resistores iguais em paralelo resultam em metade: 50 Ω.","reference":"Ato 3.448/2026, ementa Classe C","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"C006","subject":"elec","classes":"CBA","text":"Para medir tensão com um multímetro, a ligação normalmente é feita em paralelo com o ponto/carga medido.","answer":true,"explanation":"Voltímetro é ligado em paralelo.","reference":"Ato 3.448/2026, ementa Classe C","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"C007","subject":"elec","classes":"CBA","text":"Para medir corrente, o amperímetro deve normalmente ser inserido em série com o circuito.","answer":true,"explanation":"A corrente a medir deve atravessar o instrumento.","reference":"Ato 3.448/2026, ementa Classe C","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"C008","subject":"elec","classes":"CBA","text":"Um fusível tem a função principal de proteger o circuito contra corrente excessiva.","answer":true,"explanation":"O fusível abre o circuito quando a corrente excede seu limite.","reference":"Ato 3.448/2026, ementa Classe C","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"C009","subject":"elec","classes":"CBA","text":"O aterramento pode contribuir para segurança elétrica e para o funcionamento adequado de uma estação.","answer":true,"explanation":"Aterramento integra a ementa de proteção elétrica.","reference":"Ato 3.448/2026, ementa Classe C","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"C010","subject":"elec","classes":"CBA","text":"Um wattímetro é utilizado para medir potência.","answer":true,"explanation":"Wattímetro mede potência elétrica/RF conforme a aplicação.","reference":"Ato 3.448/2026, ementa Classe C","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"C011","subject":"elec","classes":"CBA","text":"Um medidor de ROE serve para avaliar o casamento entre linha de transmissão e carga/antena.","answer":true,"explanation":"Ele mede a relação de ondas estacionárias associada à potência direta e refletida.","reference":"Ato 3.448/2026, ementa Classe C","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"C012","subject":"elec","classes":"CBA","text":"Um receptor tem como função principal gerar RF de potência para alimentar a antena.","answer":false,"explanation":"Essa é função do transmissor; o receptor processa sinais recebidos.","reference":"Ato 3.448/2026, ementa Classe C","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"C013","subject":"elec","classes":"CBA","text":"Um transmissor converte a informação em um sinal de RF adequado à transmissão.","answer":true,"explanation":"O transmissor produz o sinal a ser enviado ao sistema radiante.","reference":"Ato 3.448/2026, ementa Classe C","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"C014","subject":"elec","classes":"CBA","text":"Um transceptor combina funções de transmissão e recepção.","answer":true,"explanation":"Transceptor integra transmissor e receptor.","reference":"Ato 3.448/2026, ementa Classe C","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"C015","subject":"elec","classes":"CBA","text":"A velocidade de uma onda de rádio no espaço livre é aproximadamente 300 milhões de metros por segundo.","answer":true,"explanation":"Ondas eletromagnéticas no vácuo propagam-se aproximadamente à velocidade da luz.","reference":"Ato 3.448/2026, ementa Classe C","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"C016","subject":"elec","classes":"CBA","text":"Uma frequência de 150 MHz corresponde aproximadamente a um comprimento de onda de 2 metros no espaço livre.","answer":true,"explanation":"λ≈300/f(MHz)=300/150=2 m.","reference":"Ato 3.448/2026, ementa Classe C","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"C017","subject":"elec","classes":"CBA","text":"Uma frequência de 30 MHz corresponde aproximadamente a 1 metro de comprimento de onda.","answer":false,"explanation":"λ≈300/30=10 m.","reference":"Ato 3.448/2026, ementa Classe C","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"C018","subject":"elec","classes":"CBA","text":"Um resistor é um componente destinado, entre outras funções, a limitar corrente e produzir quedas de tensão.","answer":true,"explanation":"Resistores se opõem à passagem de corrente e são usados para controle de corrente/tensão.","reference":"Ato 3.448/2026, ementa Classe C","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"C019","subject":"elec","classes":"CBA","text":"Um capacitor ideal armazena energia em campo elétrico.","answer":true,"explanation":"Capacitância está associada ao armazenamento de energia no campo elétrico.","reference":"Ato 3.448/2026, ementa Classe C","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"C020","subject":"elec","classes":"CBA","text":"Uma bobina ou indutor ideal armazena energia em campo magnético.","answer":true,"explanation":"Indutância está associada ao campo magnético.","reference":"Ato 3.448/2026, ementa Classe C","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"B001","subject":"elec","classes":"BA","text":"Pela Lei de Joule, a potência dissipada em um resistor pode ser calculada por P = I²R.","answer":true,"explanation":"É uma das formas da relação de potência em elemento resistivo.","reference":"Ato 3.448/2026, ementa Classe B","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"B002","subject":"elec","classes":"BA","text":"Em um nó de circuito, a soma algébrica das correntes é zero, conforme a Lei das Correntes de Kirchhoff.","answer":true,"explanation":"A lei expressa conservação de carga em um nó.","reference":"Ato 3.448/2026, ementa Classe B","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"B003","subject":"elec","classes":"BA","text":"Em uma malha fechada, a soma algébrica das tensões é zero, conforme a Lei das Tensões de Kirchhoff.","answer":true,"explanation":"A lei expressa conservação de energia ao longo da malha.","reference":"Ato 3.448/2026, ementa Classe B","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"B004","subject":"elec","classes":"BA","text":"Resistores de 100 Ω e 220 Ω em série equivalem a 320 Ω.","answer":true,"explanation":"Em série: 100+220=320 Ω.","reference":"Ato 3.448/2026, ementa Classe B","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"B005","subject":"elec","classes":"BA","text":"Resistores de 100 Ω e 100 Ω em paralelo equivalem a 50 Ω.","answer":true,"explanation":"Req=(100×100)/(100+100)=50 Ω.","reference":"Ato 3.448/2026, ementa Classe B","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"B006","subject":"elec","classes":"BA","text":"Resistores de 100 Ω e 200 Ω em paralelo equivalem a 300 Ω.","answer":false,"explanation":"Em paralelo o resultado é menor que o menor resistor: ≈66,7 Ω.","reference":"Ato 3.448/2026, ementa Classe B","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"B007","subject":"elec","classes":"BA","text":"No código de cores de resistores, marrom-preto-vermelho representa 1 kΩ em um resistor de quatro faixas, desconsiderando tolerância.","answer":true,"explanation":"10 × 10² = 1000 Ω.","reference":"Ato 3.448/2026, ementa Classe B","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"B008","subject":"elec","classes":"BA","text":"No código de cores, vermelho-vermelho-marrom representa 220 Ω, desconsiderando tolerância.","answer":true,"explanation":"22 × 10¹ = 220 Ω.","reference":"Ato 3.448/2026, ementa Classe B","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"B009","subject":"elec","classes":"BA","text":"A reatância capacitiva diminui quando a frequência aumenta, mantendo a capacitância constante.","answer":true,"explanation":"Xc=1/(2πfC).","reference":"Ato 3.448/2026, ementa Classe B","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"B010","subject":"elec","classes":"BA","text":"A reatância indutiva diminui quando a frequência aumenta, mantendo a indutância constante.","answer":false,"explanation":"XL=2πfL, portanto aumenta com a frequência.","reference":"Ato 3.448/2026, ementa Classe B","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"B011","subject":"elec","classes":"BA","text":"Em corrente alternada, impedância pode possuir componentes resistiva e reativa.","answer":true,"explanation":"Impedância generaliza a oposição à corrente em CA.","reference":"Ato 3.448/2026, ementa Classe B","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"B012","subject":"elec","classes":"BA","text":"Um sinal de 1 kHz possui período de 1 ms.","answer":true,"explanation":"T=1/f=1/1000 s=0,001 s.","reference":"Ato 3.448/2026, ementa Classe B","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"B013","subject":"elec","classes":"BA","text":"Um sinal de 50 Hz possui período de 20 ms.","answer":true,"explanation":"T=1/50 s=0,02 s.","reference":"Ato 3.448/2026, ementa Classe B","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"B014","subject":"elec","classes":"BA","text":"Materiais semicondutores possuem propriedades elétricas intermediárias e controláveis entre condutores e isolantes.","answer":true,"explanation":"Essa característica permite a fabricação de diodos, transistores e outros dispositivos.","reference":"Ato 3.448/2026, ementa Classe B","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"B015","subject":"elec","classes":"BA","text":"Na modulação ASK, a informação digital é representada por alterações de amplitude.","answer":true,"explanation":"ASK significa Amplitude Shift Keying.","reference":"Ato 3.448/2026, ementa Classe B","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"B016","subject":"elec","classes":"BA","text":"Na modulação FSK, a informação digital é representada por alterações de frequência.","answer":true,"explanation":"FSK significa Frequency Shift Keying.","reference":"Ato 3.448/2026, ementa Classe B","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"B017","subject":"elec","classes":"BA","text":"Na modulação PSK, a informação digital é representada por alterações de fase.","answer":true,"explanation":"PSK significa Phase Shift Keying.","reference":"Ato 3.448/2026, ementa Classe B","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"B018","subject":"elec","classes":"BA","text":"Uma antena dipolo de meia onda tem comprimento total aproximado de metade do comprimento de onda, com ajustes práticos.","answer":true,"explanation":"O dipolo meia onda é aproximadamente λ/2, sujeito a fatores de encurtamento e ambiente.","reference":"Ato 3.448/2026, ementa Classe B","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"B019","subject":"elec","classes":"BA","text":"Polarização vertical significa que o campo elétrico principal está orientado verticalmente.","answer":true,"explanation":"A polarização é definida pela orientação do campo elétrico.","reference":"Ato 3.448/2026, ementa Classe B","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"B020","subject":"elec","classes":"BA","text":"Em ressonância, reatâncias indutiva e capacitiva podem se cancelar em um circuito RLC ideal adequado.","answer":true,"explanation":"Na frequência de ressonância, XL e Xc podem ter mesmo módulo e sinais opostos.","reference":"Ato 3.448/2026, ementa Classe B","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"A001","subject":"elec","classes":"A","text":"A reatância indutiva é calculada por XL = 2πfL.","answer":true,"explanation":"Essa é a expressão da reatância de um indutor ideal.","reference":"Ato 3.448/2026, ementa Classe A","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"A002","subject":"elec","classes":"A","text":"A reatância capacitiva é calculada por XC = 2πfC.","answer":false,"explanation":"XC = 1/(2πfC).","reference":"Ato 3.448/2026, ementa Classe A","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"A003","subject":"elec","classes":"A","text":"Em um circuito série com R=30 Ω e XL=40 Ω, sem capacitância, o módulo da impedância é 50 Ω.","answer":true,"explanation":"|Z|=√(R²+XL²)=√(900+1600)=50 Ω.","reference":"Ato 3.448/2026, ementa Classe A","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"A004","subject":"elec","classes":"A","text":"Em um circuito série puramente resistivo, tensão e corrente estão em fase.","answer":true,"explanation":"Não há componente reativa para deslocar a fase.","reference":"Ato 3.448/2026, ementa Classe A","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"A005","subject":"elec","classes":"A","text":"Em um indutor ideal, a corrente atrasa a tensão em 90 graus.","answer":true,"explanation":"Comportamento ideal indutivo: tensão adianta a corrente.","reference":"Ato 3.448/2026, ementa Classe A","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"A006","subject":"elec","classes":"A","text":"Em um capacitor ideal, a corrente atrasa a tensão em 90 graus.","answer":false,"explanation":"No capacitor ideal, a corrente adianta a tensão em 90 graus.","reference":"Ato 3.448/2026, ementa Classe A","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"A007","subject":"elec","classes":"A","text":"A frequência de ressonância de um circuito LC ideal é f = 1/(2π√LC).","answer":true,"explanation":"É a expressão clássica da frequência natural de ressonância LC.","reference":"Ato 3.448/2026, ementa Classe A","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"A008","subject":"elec","classes":"A","text":"Se a capacitância de um circuito LC aumenta e a indutância permanece constante, a frequência de ressonância aumenta.","answer":false,"explanation":"Como f é inversamente proporcional a √C, a frequência diminui.","reference":"Ato 3.448/2026, ementa Classe A","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"A009","subject":"elec","classes":"A","text":"Em circuitos paralelos, a admitância é uma grandeza útil por somar diretamente os ramos ideais.","answer":true,"explanation":"Admitâncias de ramos em paralelo são somadas.","reference":"Ato 3.448/2026, ementa Classe A","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"A010","subject":"elec","classes":"A","text":"Superposição permite analisar separadamente os efeitos de fontes independentes em circuitos lineares e somar os resultados.","answer":true,"explanation":"Esse é o princípio da superposição em sistemas lineares.","reference":"Ato 3.448/2026, ementa Classe A","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"A011","subject":"elec","classes":"A","text":"Um diodo semicondutor ideal conduz igualmente nos dois sentidos.","answer":false,"explanation":"O diodo ideal conduz em um sentido e bloqueia no sentido oposto.","reference":"Ato 3.448/2026, ementa Classe A","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"A012","subject":"elec","classes":"A","text":"Um transistor pode ser utilizado para amplificação e chaveamento em circuitos eletrônicos e de RF.","answer":true,"explanation":"Transistores são elementos fundamentais de amplificadores e chaves.","reference":"Ato 3.448/2026, ementa Classe A","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"A013","subject":"elec","classes":"A","text":"Um amplificador de RF aumenta a potência ou amplitude de sinais na faixa de radiofrequência, dentro de suas especificações.","answer":true,"explanation":"Essa é uma aplicação típica de estágios ativos de RF.","reference":"Ato 3.448/2026, ementa Classe A","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"A014","subject":"elec","classes":"A","text":"Harmônicos são componentes cujas frequências são múltiplos inteiros da frequência fundamental.","answer":true,"explanation":"Essa é a definição usual de harmônicos.","reference":"Ato 3.448/2026, ementa Classe A","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"A015","subject":"elec","classes":"A","text":"Um filtro passa-baixas ideal atenua frequências acima da frequência de corte e permite as inferiores.","answer":true,"explanation":"Esse é o comportamento ideal de um filtro passa-baixas.","reference":"Ato 3.448/2026, ementa Classe A","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"A016","subject":"elec","classes":"A","text":"Ondas estacionárias em uma linha podem resultar da superposição entre onda incidente e onda refletida.","answer":true,"explanation":"A interferência entre ondas em sentidos opostos forma o padrão estacionário.","reference":"Ato 3.448/2026, ementa Classe A","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"A017","subject":"elec","classes":"A","text":"Em uma linha perfeitamente casada, não existe potência refletida idealmente.","answer":true,"explanation":"Com carga igual à impedância característica, o coeficiente de reflexão ideal é zero.","reference":"Ato 3.448/2026, ementa Classe A","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"A018","subject":"elec","classes":"A","text":"Se a ROE é exatamente 1:1, isso indica reflexão total da potência para o transmissor.","answer":false,"explanation":"ROE 1:1 representa casamento ideal e reflexão nula idealmente.","reference":"Ato 3.448/2026, ementa Classe A","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"A019","subject":"elec","classes":"A","text":"Ressonância em antenas está relacionada à distribuição de correntes e tensões e à relação entre dimensões elétricas e comprimento de onda.","answer":true,"explanation":"O comportamento ressonante depende do comprimento elétrico da antena e do ambiente.","reference":"Ato 3.448/2026, ementa Classe A","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"},{"id":"A020","subject":"elec","classes":"A","text":"Interferência destrutiva ocorre quando ondas se superpõem de modo a reduzir a amplitude resultante em determinado ponto.","answer":true,"explanation":"A soma vetorial/fásica pode produzir redução de amplitude.","reference":"Ato 3.448/2026, ementa Classe A","url":"https://informacoes.anatel.gov.br/legislacao/atos-de-requisitos-operacionais-de-outorga-e-licenciamento/2148-ato-3448-26"}];
